#[allow(clippy::too_many_arguments)]
pub(super) fn determinant_3x3(
    a11: f64,
    a12: f64,
    a13: f64,
    a21: f64,
    a22: f64,
    a23: f64,
    a31: f64,
    a32: f64,
    a33: f64,
) -> f64 {
    a11 * (a22 * a33 - a23 * a32) - a12 * (a21 * a33 - a23 * a31) + a13 * (a21 * a32 - a22 * a31)
}

/// Compute shortest edge length in tetrahedron
pub(super) fn min_edge_length(verts: &[Point; 4]) -> f64 {
    let edges = [
        (verts[0], verts[1]),
        (verts[0], verts[2]),
        (verts[0], verts[3]),
        (verts[1], verts[2]),
        (verts[1], verts[3]),
        (verts[2], verts[3]),
    ];

    let mut min_len = f64::INFINITY;
    for (p1, p2) in edges {
        let len = p1.distance(&p2);
        if len < min_len {
            min_len = len;
        }
    }
    min_len
}

/// Convert a `Point` to robust's `Coord3D<f64>`.
#[inline]
pub(super) fn rc3(p: Point) -> robust::Coord3D<f64> {
    robust::Coord3D {
        x: p.x,
        y: p.y,
        z: p.z,
    }
}

/// Signed volume of the tetrahedron (a, b, c, d): positive when (b-a, c-a,
/// d-a) forms a right-handed frame. Backed by Shewchuk's adaptive
/// `robust::orient3d`, so cocircular / coplanar inputs return the
/// mathematically exact sign rather than an IEEE-double rounding artefact.
pub(super) fn orient3d(verts: &[Point; 4]) -> f64 {
    robust::orient3d(rc3(verts[0]), rc3(verts[1]), rc3(verts[2]), rc3(verts[3]))
}

/// In-sphere predicate. Returns `true` iff `p` lies strictly inside the
/// circumsphere of the tetrahedron `verts`. Uses `robust::insphere`, which
/// expects the four tet vertices to be positively oriented — we flip the
/// last two when the input orientation is negative so the contract holds.
/// Cocircular configurations return `false` (boundary excluded), matching
/// the strict-inside convention used by Bowyer-Watson cavity discovery.
pub(super) fn in_circumsphere(p: &Point, verts: &[Point; 4]) -> bool {
    let (a, b, c, d) = (verts[0], verts[1], verts[2], verts[3]);
    let orient = robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(d));
    if orient == 0.0 {
        return false;
    }
    let (b, c) = if orient > 0.0 { (b, c) } else { (c, b) };
    robust::insphere(rc3(a), rc3(b), rc3(c), rc3(d), rc3(*p)) > 0.0
}

/// For a positively-oriented (per `robust::orient3d`) tetrahedron `[v0,v1,v2,v3]`,
