pub(super) fn push_unique(values: &mut Vec<usize>, value: usize) {
    if !values.contains(&value) {
        values.push(value);
    }
}

pub(super) fn affected_edge_vertices(edge: [usize; 2], ring: &[usize]) -> Vec<usize> {
    let mut vertices = Vec::with_capacity(ring.len() + 2);
    push_unique(&mut vertices, edge[0]);
    push_unique(&mut vertices, edge[1]);
    for &vertex in ring {
        push_unique(&mut vertices, vertex);
    }
    vertices
}

pub(super) fn cross3(a: (f64, f64, f64), b: (f64, f64, f64)) -> (f64, f64, f64) {
    (
        a.1 * b.2 - a.2 * b.1,
        a.2 * b.0 - a.0 * b.2,
        a.0 * b.1 - a.1 * b.0,
    )
}

pub(super) fn dot3(a: (f64, f64, f64), b: (f64, f64, f64)) -> f64 {
    a.0 * b.0 + a.1 * b.1 + a.2 * b.2
}

pub(super) fn norm3(v: (f64, f64, f64)) -> f64 {
    dot3(v, v).sqrt()
}

