/// Volume-weighted Lloyd relaxation. Each interior node migrates to the
/// volume-weighted centroid of its incident tets. Boundary nodes are pinned —
/// moving them would deform the surface, which is not what this pass is for.
pub(super) fn lloyd_relaxation(mesh: &mut Mesh, iterations: usize) {
    for _ in 0..iterations {
        let mut moves: HashMap<usize, Point> = HashMap::new();
        let mut accum: HashMap<usize, (f64, f64, f64, f64)> = HashMap::new();
        for elem_idx in 0..mesh.num_elements() {
            let elem = &mesh.elements[elem_idx];
            if elem.element_type != ElementType::Tetrahedron {
                continue;
            }
            let vol = mesh.element_measure(elem_idx);
            let c = mesh.element_centroid(elem_idx);
            for &n in elem.vertices() {
                let entry = accum.entry(n).or_insert((0.0, 0.0, 0.0, 0.0));
                entry.0 += c.x * vol;
                entry.1 += c.y * vol;
                entry.2 += c.z * vol;
                entry.3 += vol;
            }
        }
        for (node_idx, (wx, wy, wz, w_sum)) in accum {
            if is_boundary_node(mesh, node_idx) || w_sum <= 0.0 {
                continue;
            }
            moves.insert(node_idx, Point::new_3d(wx / w_sum, wy / w_sum, wz / w_sum));
        }
        for (idx, p) in moves {
            mesh.nodes[idx] = p;
        }
        mesh.invalidate_caches();
    }
}

pub(super) fn apply_boundary_markers_in_detection_order(
    mesh: &mut Mesh,
    facet_markers: Option<&[i32]>,
) {
    if let Some(markers) = facet_markers {
        for (i, boundary) in mesh.boundaries.iter_mut().enumerate() {
            if i < markers.len() {
                boundary.marker = markers[i];
            }
        }
        mesh.invalidate_caches();
    }
}

/// Apply Laplacian smoothing to improve mesh quality
pub(super) fn laplacian_smoothing(mesh: &mut Mesh, max_iterations: usize) {
    for _ in 0..max_iterations {
        let mut node_moves: HashMap<usize, Point> = HashMap::new();

        for (node_idx, _) in mesh.nodes.iter().enumerate() {
            if is_boundary_node(mesh, node_idx) {
                continue;
            }

            let neighbors = get_node_neighbors(mesh, node_idx);
            if neighbors.is_empty() {
                continue;
            }

            let mut cx = 0.0;
            let mut cy = 0.0;
            let mut cz = 0.0;

            for &nbr in &neighbors {
                let n = &mesh.nodes[nbr];
                cx += n.x;
                cy += n.y;
                cz += n.z;
            }

            let n = neighbors.len() as f64;
            node_moves.insert(node_idx, Point::new_3d(cx / n, cy / n, cz / n));
        }

        for (idx, new_pos) in node_moves {
            mesh.nodes[idx] = new_pos;
        }
    }
}

pub(super) fn is_boundary_node(mesh: &Mesh, node_idx: usize) -> bool {
    for boundary in &mesh.boundaries {
        if boundary.nodes.contains(&node_idx) {
            return true;
        }
    }
    false
}

pub(super) fn get_node_neighbors(mesh: &Mesh, node_idx: usize) -> Vec<usize> {
    let mut neighbors: HashSet<usize> = HashSet::new();

    for elem in &mesh.elements {
        if elem.nodes.contains(&node_idx) {
            for &n in &elem.nodes {
                if n != node_idx {
                    neighbors.insert(n);
                }
            }
        }
    }

    // Neighbor order affects floating-point accumulation in Laplacian
    // smoothing.  HashSet iteration is intentionally randomized, so make the
    // reduction order part of the deterministic mesher contract.
    let mut neighbors: Vec<_> = neighbors.into_iter().collect();
    neighbors.sort_unstable();
    neighbors
}
